import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.Cs5aHXsR.js";import"./chunks/assets.CN5ja4nF.js";var a=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ntfy-mcp","text":"Notifications your MCP client can send, read back and correct","tagline":"An MCP server for ntfy: publish notifications, read back what was sent, revise one in place while a job runs, and administer accounts and topic access.","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Tools reference","link":"/reference/tools"},{"theme":"alt","text":"GitHub","link":"https://github.com/ni-c/ntfy-mcp"}]},"features":[{"title":"A progress report stays one notification","details":"The id publish_message returns is also the sequence id of the notification, and update_message replaces its content in place. Subscribers watch one notification change from \\"building\\" to \\"deployed\\" instead of collecting five."},{"title":"NTFY_TOPICS is the fence","details":"On ntfy a topic name is a bearer credential — knowing it is often the whole of the access control. One variable names the topics this server may touch and supplies the default when a tool omits one, so the name stays out of the tool arguments and every read and write is bounded by the same list."},{"title":"Only the tools you want","details":"NTFY_READ_ONLY=true registers the read tools and nothing else. NTFY_ALLOW_TOOLS cuts finer — essential for a curated six, your own comma-separated list, or a whole family with list_* — and NTFY_DENY_TOOLS subtracts. Whatever is filtered out does not exist on the protocol rather than failing when called, and a name that matches no tool stops the server at startup instead of quietly going missing."},{"title":"Careful with what it hands back","details":"Deleting anything, and creating or re-scoping an account, asks a person first through MCP elicitation — a dialog the model cannot answer on its behalf, falling back to a token bound to the exact target where the client cannot show one. Notification content is marked as untrusted data, access tokens are stripped out of get_account, and a click or action URL must be http or https because the recipient device is what opens it."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788380633000}`),o={name:`index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[t(`figure`,{class:`diagram`},[t(`svg`,{viewBox:`0 0 820 280`,role:`img`,"aria-labelledby":`arch-title arch-desc`},[t(`title`,{id:`arch-title`},`ntfy-mcp architecture`),t(`desc`,{id:`arch-desc`},`An MCP client talks to ntfy-mcp over stdio; ntfy-mcp publishes notifications and polls the message cache over HTTPS against an ntfy server, which pushes them to the subscribed devices. Because a published message keeps its sequence id, the same notification can be revised in place instead of sending another one.`),t(`defs`,null,[t(`marker`,{id:`arch-arrow`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})]),t(`marker`,{id:`arch-arrow-accent`,class:`accent`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})])]),t(`rect`,{class:`node`,x:`20`,y:`70`,width:`160`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`100`,y:`103`,"text-anchor":`middle`},`MCP client`),t(`text`,{class:`label-muted`,x:`100`,y:`123`,"text-anchor":`middle`},`Claude, Codex, …`),t(`rect`,{class:`node-accent`,x:`290`,y:`55`,width:`170`,height:`110`,rx:`10`}),t(`text`,{class:`label-title`,x:`375`,y:`87`,"text-anchor":`middle`},`ntfy-mcp`),t(`text`,{class:`label-muted`,x:`375`,y:`107`,"text-anchor":`middle`},`13 tools`),t(`text`,{class:`label-muted`,x:`375`,y:`125`,"text-anchor":`middle`},`topic allow-list`),t(`text`,{class:`label-muted`,x:`375`,y:`143`,"text-anchor":`middle`},`asks a person`),t(`rect`,{class:`node`,x:`610`,y:`70`,width:`150`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`685`,y:`103`,"text-anchor":`middle`},`ntfy`),t(`text`,{class:`label-muted`,x:`685`,y:`123`,"text-anchor":`middle`},`pub-sub server`),t(`path`,{class:`edge-accent`,d:`M180,110 L282,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`231`,y:`98`,"text-anchor":`middle`},`stdio`),t(`path`,{class:`edge-accent`,d:`M460,95 L602,95`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`531`,y:`83`,"text-anchor":`middle`},`HTTPS · publish`),t(`path`,{class:`edge-accent`,d:`M460,130 L602,130`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`531`,y:`152`,"text-anchor":`middle`},`HTTPS · poll`),t(`path`,{class:`edge edge-dashed`,d:`M685,150 L685,196`,"marker-end":`url(#arch-arrow)`}),t(`text`,{class:`label-muted`,x:`685`,y:`216`,"text-anchor":`middle`},`subscribed devices get the push`),t(`text`,{class:`label-muted`,x:`685`,y:`232`,"text-anchor":`middle`},`update_message revises it in place`)]),t(`figcaption`,null,`One stdio server between the MCP client and ntfy — publishes over HTTPS and polls the message cache over the same API, bounded by the topic allow-list, with destructive calls put to a person first.`)],-1),r(`<h2 id="see-it-in-action" tabindex="-1">See it in action <a class="header-anchor" href="#see-it-in-action" aria-label="Permalink to “See it in action”">​</a></h2><p><img src="/demo.gif" alt="Demo of ntfy-mcp over the MCP inspector" width="1200" height="700"></p><h2 id="running-it-elsewhere" tabindex="-1">Running it elsewhere <a class="header-anchor" href="#running-it-elsewhere" aria-label="Permalink to “Running it elsewhere”">​</a></h2><p>A client that cannot spawn a local process — ChatGPT connectors, Claude on the web, Cursor, LibreChat — cannot start ntfy-mcp the way Claude Code does. <a href="https://mcp-hub.ni-c.de" target="_blank" rel="noreferrer">mcp-hub</a> is the bridge: one container serves many stdio MCP servers over Streamable HTTP, with an OAuth 2.1 login behind a single password and long-lived tokens for the clients that cannot do OAuth. Its <code>/hub</code> endpoint puts every server behind six meta-tools, so one connector reaches all of them without N×tool schemas in the model&#39;s context, and it speaks both protocol revisions — a question this server asks travels through it to the person at the far end instead of ending at the gateway.</p><p>Its configuration is Claude Code&#39;s <code>mcpServers</code> format, so the entry you already have is the entry it takes: <a href="/guide/clients#through-mcp-hub">Through mcp-hub</a>.</p>`,5)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};